/**
 * The promises of a store in one band: free delivery, returns, warranty, help. Axes: layout (strip: one muted
 * panel, cards: a card each, bar: a thin line of icons and titles), tone, density.
 */
import { type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { Grid } from "../primitives/grid/grid";
import { Inline } from "../primitives/inline/inline";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Feature } from "./feature-grid.types";

export type UspStripProps = {
  id: string;
  title?: string;
  perks: Feature[];
  layout?: "strip" | "cards" | "bar";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function UspStrip({
  id,
  title = "",
  perks,
  layout = "strip",
  tone = "default",
  density = "default",
  landmarkLabel,
}: UspStripProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} density={density} landmarkLabel={landmarkLabel}>
      {((layout as string) === "bar") ? (
        <List tag="ul" className="flex flex-wrap items-center justify-center gap-x-8 gap-y-4" data-testid="items">
          {(perks ?? []).map((p) => (
            <ListItem key={p.id} className="flex items-center gap-2 text-sm font-medium" data-testid="item">
              <LucideIcon name={p.icon} size={16} />
              <Inline>
                {p.title}
              </Inline>
            </ListItem>
          ))}
        </List>
      ) : (
        <Grid
          cols="1-4"
          className={cn("gap-4", (((layout as string) === "strip") ? "rounded bg-muted p-6" : ""))}
          data-testid="items"
        >
          {(perks ?? []).map((p) => (
            <Stack key={p.id}
              gap="4"
              className={
                (layout as string) === "cards" ? "rounded bg-card inset-ring inset-ring-border p-6"
                : ""
              }
              data-testid="item"
            >
              <Box className="flex size-10 shrink-0 items-center justify-center rounded bg-muted">
                <LucideIcon name={p.icon} size={20} />
              </Box>
              <Stack gap="2">
                <Text size="sm" weight="semibold">
                  {p.title}
                </Text>
                <Text size="sm" className="text-muted-foreground">
                  {p.text}
                </Text>
              </Stack>
            </Stack>
          ))}
        </Grid>
      )}
    </SectionFrame>
  );
}
